import random

class Character:
    def __init__(self, name, initial_traits):
        self.name = name
        self.traits = {trait: weight for trait, weight in initial_traits.items()}
        self.trait_weights = {trait: weight for trait, weight in initial_traits.items()}
        self.memory = []  # 对话历史
        self.context = {}  # 对话上下文
        self.responses = {
            "friendly": ["Hello!", "What's up?"],
            "suspicious": ["Who are you?", "I'm not sure I can trust you."],
            "happy": ["Great to see you!", "I'm feeling great today!"],
            "angry": ["I'm not in the mood for this!", "Why are you bothering me?"],
            "sad": ["I'm not feeling well...", "I could use some cheering up."]
        }
        self.normalize_traits()

    def normalize_traits(self):
        total = sum(self.trait_weights.values())
        self.trait_weights = {trait: weight / total for trait, weight in self.trait_weights.items()}

    def update_traits(self, input_text):
        # Adjust traits based on input text with a decay factor to reduce the impact over time
        decay_factor = 0.9
        for trait in self.traits:
            self.traits[trait] *= decay_factor
        adjustments = {
            "happy": 0.1, "sad": -0.1, "angry": 0.2
        }
        for emotion, adjustment in adjustments.items():
            if emotion in input_text.lower():
                for trait in self.traits:
                    self.traits[trait] += self.traits[trait] * adjustment
        self.normalize_traits()

    def process_feedback(self, feedback, dominant_trait):
        # Adjust traits based on feedback with a dynamic learning rate
        if feedback == "positive":
            self.traits[dominant_trait] += 0.1  # Increase the learning rate for positive feedback
        elif feedback == "negative":
            self.traits[dominant_trait] -= 0.1  # Increase the learning rate for negative feedback
        self.normalize_traits()

    def learn_from_interaction(self, input_text, feedback):
        # Learn from the interaction by updating traits and processing feedback
        self.update_traits(input_text)
        dominant_trait = max(self.trait_weights, key=self.trait_weights.get)
        self.process_feedback(feedback, dominant_trait)
        self.memory.append((input_text, dominant_trait, feedback))  # 记录对话历史

    def generate_response(self):
        # Generate a response based on the current traits and context
        dominant_trait = max(self.trait_weights, key=self.trait_weights.get)
        response = random.choice(self.responses.get(dominant_trait, ["I'm not sure how to respond."]))

        # Consider the last interaction for context-based response
        if self.memory:
            last_input, last_dominant_trait, last_feedback = self.memory[-1]
            if last_feedback == "negative" and "sad" in self.responses:
                response = random.choice(self.responses["sad"])
            elif "thank" in last_input.lower() and "happy" in self.responses:
                response = random.choice(self.responses["happy"])

        # Update context based on the last input and response
        self.context["last_input"] = last_input
        self.context["last_response"] = response
        return response

    def display_traits(self):
        # Display the current traits
        print(f"{self.name}'s traits: {self.trait_weights}")

# Example usage:
char = Character("Alice", {"friendly": 0.5, "suspicious": 0.3, "happy": 0.2, "angry": 0.0, "sad": 0.0})
char.display_traits()
print(char.generate_response())

# Simulating conversation and trait updates
user_input = "I'm feeling really sad today."
char.learn_from_interaction(user_input, "negative")
char.display_traits()
print(char.generate_response())

user_input = "But I'm getting better now, thanks to you!"
char.learn_from_interaction(user_input, "positive")
char.display_traits()
print(char.generate_response())

